def test_remote_reader_excludes_old_logs_and_detects_rotation_and_size_cap(helper, tmp_path):
    paths = {p: tmp_path / p.rsplit("/", 1)[1] for p in ("/var/log/gnmi.log", "/var/log/syslog")}
    for file in paths.values():
        file.write_text("old record\n")

    def shell(command, **kwargs):
        assert kwargs["module_async"]
        args = shlex.split(command)
        script = args[args.index("-c") + 1]
        for remote, local in paths.items():
            script = script.replace(remote, str(local))
        output = subprocess.check_output([sys.executable, "-c", script, args[-1]], text=True, timeout=5)
        return Mock(), SimpleNamespace(get=lambda timeout: {"rc": 0, "stdout": output})

    dut = SimpleNamespace(shell=shell)
    baseline = helper["_read_diagnostic_logs"](dut, None, 5)
    for file in paths.values():
        with file.open("a") as stream:
            stream.write("fresh record\n")
    logs = helper["_read_diagnostic_logs"](dut, baseline, 5)
    assert all(entry["text"] == "fresh record\n" for entry in logs.values())
    gnmi = paths["/var/log/gnmi.log"]
    with gnmi.open("a") as stream:
        stream.write("bounded record\n" * 10000)
    logs = helper["_read_diagnostic_logs"](dut, baseline, 5)
    assert len(logs[str(gnmi)]["text"].encode()) <= 65536
    assert "prefix omitted" in logs[str(gnmi)]["gap"]
    gnmi.rename(tmp_path / "gnmi.log.1")
    gnmi.write_text("replacement\n")
    logs = helper["_read_diagnostic_logs"](dut, baseline, 5)
    assert "text" not in logs[str(gnmi)]
    assert "rotated" in logs[str(gnmi)]["gap"]
    syslog = paths["/var/log/syslog"]
    syslog.write_text("")
    logs = helper["_read_diagnostic_logs"](dut, baseline, 5)
    assert "text" not in logs[str(syslog)]


def test_stalled_ssh_wait_is_bounded_and_baseline_is_optional(helper):
    pool = Mock()
    pending = Mock()
    pending.get.side_effect = TimeoutError("SSH stalled")
    pending.ready.return_value = False
    dut = Mock()
    dut.shell.return_value = pool, pending
    with pytest.raises(helper["DiagnosticReadPending"]):
        helper["get_diagnostic_log_cursors"](dut)
    assert 0 < pending.get.call_args.kwargs["timeout"] <= 5
    assert "sudo timeout -k 1" in dut.shell.call_args.args[0]
    pool.close.assert_called_once()
    pool.terminate.assert_not_called()
    pool.join.assert_not_called()

    pending.ready.return_value = True
    assert helper["get_diagnostic_log_cursors"](dut) == {}


def test_delayed_real_worker_cannot_reach_open_channel(helper):
    release = threading.Event()
    worker_started = threading.Event()
    channel_open = threading.Event()
    fork_observations = []
    pool = ThreadPool(1)

    def delayed_ansible():
        worker_started.set()
        release.wait(2)
        # Models Ansible's late fork point after delayed dispatch/SSH setup.
        fork_observations.append(channel_open.is_set())
        return {"rc": 0, "stdout": "{}"}

    pending = pool.apply_async(delayed_ansible)
    assert worker_started.wait(1)
    dut = SimpleNamespace(shell=lambda *args, **kwargs: (pool, pending))
    original = helper["_read_diagnostic_logs"]
    helper["_read_diagnostic_logs"] = lambda dut, cursors, timeout: original(dut, cursors, 0.02)
    try:
        with pytest.raises(helper["DiagnosticReadPending"]):
            helper["get_diagnostic_log_cursors"](dut)
            channel_open.set()  # Must be unreachable while the worker is pending.
    finally:
        release.set()
        pending.get(timeout=2)
        pool.join()
    assert fork_observations == [False]
    assert not channel_open.is_set()


def test_observation_keeps_late_completion_and_charges_remote_latency(helper, tmp_path, monkeypatch):
    monkeypatch.chdir(tmp_path)
    clock = SimpleNamespace(now=0.0)

    def sleep(seconds):
        clock.now += seconds

    helper["time"] = SimpleNamespace(monotonic=lambda: clock.now, time=lambda: clock.now, sleep=sleep)
    record = {"method": "/gnmi.gNMI/Set", "principal": "client", "path": ["/PORT/x"],
              "code": "OK", "duration_ms": 65000}
    budgets = []

    def read(dut, cursors, timeout):
        budgets.append(timeout)
        sleep(timeout)
        return {"/var/log/gnmi.log": {"text": "RPC_COMPLETION " + json.dumps(record)}}

    helper["_read_diagnostic_logs"] = read
    helper["collect_rpc_timeout_evidence"](
        SimpleNamespace(hostname="dut"), {"baseline": True}, [{"status": "DEADLINE_EXCEEDED"}],
        "/gnmi.gNMI/Set", "client", "/PORT/x", timeout=12)
    evidence = json.loads(next(tmp_path.glob("logs/gnmi/*/evidence.json")).read_text())
    assert clock.now == 12
    assert budgets == [10]
    assert evidence["calls"][0]["status"] == "DEADLINE_EXCEEDED"
    assert evidence["snapshots"][0]["completion_candidates"] == [record]
    assert "original client failure" in evidence["result"]
    assert "ambiguous" in evidence["correlation"]


def test_collection_error_is_saved_without_launching_more_readers(helper, tmp_path, monkeypatch):
    monkeypatch.chdir(tmp_path)
    read = Mock(side_effect=TimeoutError("SSH stalled"))
    helper["_read_diagnostic_logs"] = read
    helper["collect_rpc_timeout_evidence"](
        SimpleNamespace(hostname="dut"), {"baseline": True}, [], "/gnmi.gNMI/Set", "client", "/PORT/x")
    evidence = json.loads(next(tmp_path.glob("logs/gnmi/*/evidence.json")).read_text())
    read.assert_called_once()
    assert evidence["snapshots"][0]["collection_error"] == "SSH stalled"


@pytest.mark.parametrize("fail_at,diagnostic_fails", [(None, False), (0, False), (1, True)])
def test_stress_deadline_and_channel_closure_preserve_original_error(fail_at, diagnostic_fails):
    events = []
    deadline_code = SimpleNamespace(name="DEADLINE_EXCEEDED")

    class RpcError(Exception):
        def code(self):
            return deadline_code

    original = RpcError("original deadline")
    client = Mock()

    def set_rpc(request, timeout):
        assert timeout == 60
        events.append(request)
        if fail_at is not None and len(events) - 1 == fail_at:
            raise original

    client.Set.side_effect = set_rpc
    state = SimpleNamespace(open=False)

    @contextmanager
    def connection(fixture):
        state.open = True
        try:
            yield object(), client
        finally:
            state.open = False

    def baseline(dut):
        assert not state.open
        return {}

    def collect(*args, **kwargs):
        assert not state.open
        assert args[2][-1]["status"] == "DEADLINE_EXCEEDED"
        if diagnostic_fails:
            raise RuntimeError("diagnostic failed")

    collector = Mock(side_effect=collect)
    namespace = load_functions(COMMON.parent / "gnmi/test_gnmi_stress.py", {
        "time": time, "json": json, "logger": Mock(), "pytest": pytest,
        "grpc": SimpleNamespace(RpcError=RpcError, StatusCode=SimpleNamespace(DEADLINE_EXCEEDED=deadline_code),
                                channel_ready_future=lambda channel: Mock()),
        "gnmi_connection": connection, "get_diagnostic_log_cursors": baseline,
        "collect_rpc_timeout_evidence": collector,
        "build_native_set_request": lambda parts, value: value,
    })
    dut = Mock()
    dut.is_supervisor_node.return_value = False
    dut.shell.return_value = {"stdout": "cpu"}
    namespace["get_first_interface"] = lambda dut: "Ethernet0"
    run = namespace["test_gnmi_latency_01"]
    if fail_at is None:
        run({"dut": dut}, "dut", None, object())
        assert events == ["down", "up"] * 10
        collector.assert_not_called()
    else:
        with pytest.raises(RpcError) as caught:
            run({"dut": dut}, "dut", None, object())
        assert caught.value is original
        collector.assert_called_once()
        assert len(events) == fail_at + 1
